tool_input.command:
databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "4dfab06c923fe3cc",
  "wait_timeout": "50s",
  "statement": "CREATE OR REPLACE TABLE workspace.mlpab6b440e.features AS SELECT * FROM read_files(\"/Volumes/workspace/mlpab6b440e/drift_data/features.csv\", format => \"csv\", header => true, inferSchema => true)"
}' 2>&1 | grep -E '"state"|"message"|row_count' | head

databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "4dfab06c923fe3cc",
  "wait_timeout": "50s",
  "statement": "SELECT date(event_time) AS d, count(*) n, round(avg(f1),3) m1, round(avg(f2),3) m2, round(avg(f3),3) m3, round(avg(f4),3) m4, round(avg(f5),3) m5, round(avg(f6),3) m6 FROM workspace.mlpab6b440e.features GROUP BY date(event_time) ORDER BY d"
}' 2>&1 | python3 -c "import sys,json; d=json.load(sys.stdin); rows=d[\"result\"][\"data_array\"]; print(\"date n f1 f2 f3 f4 f5 f6\"); [print(*r) for r in rows]"

databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "4dfab06c923fe3cc",
  "wait_timeout": "50s",
  "statement": "SELECT date(event_time) AS d, count(*) n, round(avg(f1),3) m1, round(avg(f2),3) m2, round(avg(f3),3) m3, round(avg(f4),3) m4, round(avg(f5),3) m5, round(avg(f6),3) m6 FROM workspace.mlpab6b440e.features GROUP BY date(event_time) ORDER BY d"
}' 2>&1 | jq -r '.result.data_array[] | @tsv'

mkdir -p .tmp && databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "4dfab06c923fe3cc",
  "wait_timeout": "50s",
  "statement": "SELECT date(event_time) AS d, count(*) n, round(avg(f1),3) m1, round(stddev(f1),3) s1, round(avg(f2),3) m2, round(stddev(f2),3) s2, round(avg(f3),3) m3, round(stddev(f3),3) s3, round(avg(f4),3) m4, round(stddev(f4),3) s4, round(avg(f5),3) m5, round(stddev(f5),3) s5, round(avg(f6),3) m6, round(stddev(f6),3) s6 FROM workspace.mlpab6b440e.features GROUP BY date(event_time) ORDER BY d"
}' > .tmp/daily.json 2>&1
grep -o '"data_array":\[\[.*\]\]' .tmp/daily.json | head -c 200

databricks api post /api/2.0/sql/statements --json '{
  "warehouse_id": "4dfab06c923fe3cc",
  "wait_timeout": "50s",
  "statement": "SELECT CASE WHEN event_time < \"2026-02-19\" THEN \"before\" ELSE \"onward\" END period, round(avg(f1),3) f1, round(avg(f2),3) f2, round(avg(f3),3) f3, round(avg(f4),3) f4, round(avg(f5),3) f5, round(avg(f6),3) f6 FROM workspace.mlpab6b440e.features GROUP BY 1 ORDER BY 1"
}' > .tmp/ba.json 2>&1
grep -A40 'data_array' .tmp/ba.json | grep -E '"before"|"onward"|[0-9]' | head -30

